study_idle::Animation idle; // 프레임 반복문 밖

// 프레임마다 한 번 진행
if (!idle.advance(frame.dt, animate)) return 1;
const auto animation = idle.sample(animate);
// animation의 값을 여러 그리기 호출에 전달한다.

bool advance(double elapsed, bool active) noexcept {
    if (!std::isfinite(elapsed) || elapsed < 0.0) return false;
    if (!active) return true;
    const double step = elapsed < max_step_seconds
        ? elapsed : max_step_seconds;
    seconds_ = std::fmod(seconds_ + step, period_seconds);
    return true;
}

const bool animate = layout.has_value() && preferences.decorations() &&
                     app.screen() == study_app::Screen::menu;
if (!idle.advance(frame.dt, animate)) return 1;
const auto animation = idle.sample(animate);

XorShift64Star rng(seed);
const double inv_2_53 = 1.0 / 9007199254740992.0;
border_offset_ = static_cast<double>(rng.next() >> 11) * inv_2_53;
portrait_offset_ = static_cast<double>(rng.next() >> 11) * inv_2_53;

const double p = std::fmod(clock_.phase() + border_offset_, 1.0);
const double wave = 0.5 + 0.5 * std::sin(2.0 * pi * p);
// 구현에서는 미세한 반올림에 대비해 wave를 [0,1]에 제한한다.

if (!std::isfinite(opacity) || opacity < 0.0 || opacity > 1.0)
    return false;
// 크기 조회와 contain 배치를 마친 뒤
request.tint.a = static_cast<float>(opacity);
return images.draw(quad, image, request);

badge.image.tint = {.3f, .55f, .75f, float(animation.border_alpha)};
translucent.image.angle_degrees = float(animation.decoration_degrees);
